   681		/*empty text sample*/
   682		if (!data || !dataLength) {
   683			return gf_isom_new_text_sample();
   684		}
   685	
   686		bs = gf_bs_new(data, dataLength, GF_BITSTREAM_READ);
   687		s = gf_isom_parse_text_sample(bs);
   688		gf_bs_del(bs);
   689		return s;
   690	}
